begin;
select plan(13);
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000901','invoice-staff@example.test'),('00000000-0000-4000-8000-000000000902','invoice-accounting@example.test');
update public.profiles set role=case when id='00000000-0000-4000-8000-000000000901' then 'staff'::public.app_role else 'accounting'::public.app_role end where id in('00000000-0000-4000-8000-000000000901','00000000-0000-4000-8000-000000000902');
insert into public.brands(id,name) values('00000000-0000-4000-8000-000000000903','Invoice fixture');
insert into public.customers(id,legal_name) values('00000000-0000-4000-8000-000000000904','Fiscal customer');
insert into public.seasons(id,brand_id,code,name) values('00000000-0000-4000-8000-000000000905','00000000-0000-4000-8000-000000000903','INVOICE','Invoice fixture');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000901';
create temporary table invoice_fixture(order_id uuid,invoice_id uuid,party jsonb,lines jsonb);
insert into invoice_fixture(order_id,party,lines) values(public.save_order(null,'{"brand_id":"00000000-0000-4000-8000-000000000903","customer_id":"00000000-0000-4000-8000-000000000904","season_id":"00000000-0000-4000-8000-000000000905","order_date":"2033-01-01","discount_pct":0}','[]'),'{"legal_name":"Fiscal snapshot","vat_number":"12345678901","tax_code":"","sdi_code":"0000000","pec":"","address":{"street":"Via di prova","postal_code":"00100","city":"Roma","province":"RM","country":"IT"}}','[{"name":"Test","sku":"TEST","variant":"Nero / M","quantity":2,"unit_price_cents":1000,"discount_pct":0,"vat_rate":22,"net_cents":2000,"vat_cents":440}]');
insert into public.invoices(id,number,brand_id,customer_id,order_id,issue_date,due_date,net_cents,vat_cents,gross_cents,provider,supplier_snapshot,customer_snapshot,lines_snapshot)
select '00000000-0000-4000-8000-000000000906','INV-TEST','00000000-0000-4000-8000-000000000903','00000000-0000-4000-8000-000000000904',order_id,'2033-01-01','2033-02-01',2000,440,2440,'mock',party,party,lines from invoice_fixture;
select throws_ok($$update public.invoices set customer_snapshot='{}' where id='00000000-0000-4000-8000-000000000906'$$,'23514',null,'fiscal snapshots immutable even while draft');
select throws_ok($$update public.invoices set gross_cents=2441 where id='00000000-0000-4000-8000-000000000906'$$,'23514',null,'amount snapshot immutable');
select throws_ok($$update public.invoices set order_discount_pct=10 where id='00000000-0000-4000-8000-000000000906'$$,'23514',null,'order discount snapshot immutable');
select throws_ok($$delete from public.invoices where id='00000000-0000-4000-8000-000000000906'$$,'42501',null,'no physical invoice deletion');
select throws_ok($$insert into public.invoices(number,brand_id,customer_id,order_id,issue_date,due_date,net_cents,vat_cents,gross_cents,provider,supplier_snapshot,customer_snapshot,lines_snapshot) select 'BAD-TOTALS','00000000-0000-4000-8000-000000000903','00000000-0000-4000-8000-000000000904',order_id,'2033-01-01','2033-02-01',2001,440,2441,'mock',party,party,lines from invoice_fixture$$,'23514',null,'snapshot totals must match the lines');
select lives_ok($$update public.invoices set status='issued',external_id='mock_fixture' where id='00000000-0000-4000-8000-000000000906'$$,'provider state can evolve without editing fiscal data');
insert into public.payments(id,invoice_id,brand_id,amount_cents,paid_at,method) values('00000000-0000-4000-8000-000000000907','00000000-0000-4000-8000-000000000906','00000000-0000-4000-8000-000000000903',1000,'2033-01-02T10:00Z','bank_transfer');
select throws_ok($$update public.payments set amount_cents=1001 where id='00000000-0000-4000-8000-000000000907'$$,'42501',null,'payments immutable');
select throws_ok($$delete from public.payments where id='00000000-0000-4000-8000-000000000907'$$,'42501',null,'payments cannot be physically deleted');
select is((select count(*) from public.audit_log where table_name='payments' and record_id='00000000-0000-4000-8000-000000000907'),1::bigint,'payment insert has transactional audit');
grant select on invoice_fixture to authenticated;
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000902';
select is((select count(*) from public.payments where invoice_id='00000000-0000-4000-8000-000000000906'),1::bigint,'accounting reads payments');
select throws_ok($$insert into public.payments(invoice_id,brand_id,amount_cents,paid_at,method) values('00000000-0000-4000-8000-000000000906','00000000-0000-4000-8000-000000000903',100,'2033-01-02T10:00Z','cash')$$,'42501',null,'even accounting uses a transaction RPC rather than direct insert');
with x as(update public.invoices set status='paid' where id='00000000-0000-4000-8000-000000000906' returning id) select is((select count(*) from x),0::bigint,'invoice status is not directly writable');
reset role;update public.customers set legal_name='Changed master data' where id='00000000-0000-4000-8000-000000000904';set local role authenticated;
select is((select customer_snapshot->>'legal_name' from public.invoices where id='00000000-0000-4000-8000-000000000906'),'Fiscal snapshot','fiscal history independent of customer master data');
select * from finish();rollback;
